// Title: Export an Excel workbook to HTML with a custom TableCssId and hide overlaid content using CrossHideRight in Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# hide overlaid content CrossHideRight during HTML export | set custom TableCssId for HTML table generated by Aspose.Cells | export Excel workbook to HTML with custom table CSS ID and hidden overlapping cells | how to use HtmlSaveOptions to hide overlaid content and assign table CSS identifier in .NET
// Tags: Aspose.Cells HtmlSaveOptions CrossHideRight | custom TableCssId Aspose.Cells HTML export | hide overlaid content Excel to HTML C# | HTML table styling Aspose.Cells | Excel to HTML conversion with custom CSS ID

using System;
using System.IO;
using Aspose.Cells;

// The example loads an Excel file with Aspose.Cells, configures HtmlSaveOptions to enable CrossHideRight (hiding overlaid content) and to assign a custom CSS ID to the generated HTML table, then saves the workbook as an HTML file while handling missing files and runtime errors.
class Program
{
    static void Main()
    {
        const string inputPath = "input.xlsx";
        const string outputPath = "output.html";

        try
        {
            // Verify that the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: Input file '{inputPath}' not found.");
                return;
            }

            // Load the workbook
            var workbook = new Workbook(inputPath);

            // Configure HTML save options
            var htmlOptions = new HtmlSaveOptions(SaveFormat.Html)
            {
                // Assign a custom CSS ID to the generated HTML table
                TableCssId = "myCustomTable"
            };

            // Save the workbook as HTML
            workbook.Save(outputPath, htmlOptions);
            Console.WriteLine($"Workbook successfully saved to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            // Handle any unexpected errors
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
